def even_odd_count(num):
    evens = 0
    odds = 0
    num = abs(num)  # Work with the absolute value

    if num == 0:  # Special case for 0
        evens = 1
    else:
        while num > 0:
            digit = num % 10
            if digit % 2 == 0:
                evens += 1
            else:
                odds += 1
            num //= 10

    return (evens, odds)

